const $=id=>document.getElementById(id),form=$('auth-form'),fields=$('fields'),message=$('message');
const modes={login:['Welcome back.','Sign in to your POIGAI stakeholder account.','Sign in securely ↗'],register:['Make your first connection.','Create your account, then verify your email.','Create account ↗'],forgot:['Forgot your password?','Enter your account email for a single-use recovery link.','Send recovery email ↗'],resend:['Verify your email.','Request a new link if the first one expired or did not arrive.','Send verification email ↗'],verify:['Confirm your email.','Complete stage 02 to enable sign-in.','Verify my email ↗'],reset:['Choose a new password.','Use a long, unique password for your POIGAI account.','Save new password ↗']};
let mode='login',token='',available=false,busy=false;
const types={ngo:'NGO / Community organisation',corporate:'Corporate / CSR team',technical:'Technical / Implementation partner',proponent:'Project proponent / Community representative'};
function feedback(text,error=false){message.textContent=text;message.classList.toggle('error',error);}
function step(current){['account','verify','login'].forEach((s,i)=>{const el=$('step-'+s);el.classList.toggle('complete',i<current);if(i===current)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});}
function render(next){mode=modes[next]?next:'login';feedback('');$('auth-panel').hidden=false;$('account-panel').hidden=true;const [title,description,button]=modes[mode];$('form-title').textContent=title;$('form-description').textContent=description;$('submit').textContent=button;form.querySelectorAll('[data-for]').forEach(group=>{const show=group.dataset.for.split(' ').includes(mode);group.hidden=!show;group.querySelectorAll('input,select').forEach(input=>{input.disabled=!show;input.required=show;});});$('password').value='';$('confirm').value='';$('password').autocomplete=mode==='login'?'current-password':'new-password';document.querySelectorAll('.tabs a').forEach(a=>{if(a.dataset.mode===mode)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});fields.disabled=!available;step(mode==='register'?0:mode==='verify'||mode==='resend'?1:2);}
async function api(path,data){const response=await fetch('/api/auth/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},credentials:'same-origin',body:data?JSON.stringify(data):undefined,cache:'no-store'});let result;try{result=await response.json();}catch{throw new Error('Account services are being prepared. Please return soon.');}if(!response.ok)throw new Error(result.error||'Please try again later.');return result;}
function showAccount(user){$('auth-panel').hidden=true;$('account-panel').hidden=false;$('welcome').textContent=`Welcome, ${user.name}.`;$('user-email').textContent=user.email;$('user-org').textContent=user.organisation;$('user-type').textContent=types[user.stakeholderType]||'Stakeholder';step(3);token='';history.replaceState(null,'',location.pathname);form.reset();}
function navigate(){const fragment=location.hash.slice(1),match=/^(verify|reset)=([a-f0-9]{64})$/.exec(fragment);if(match){token=match[2];render(match[1]);history.replaceState(null,'',location.pathname);return;}if(['verify','reset'].includes(mode)&&token&&!fragment)return;token='';if(fragment==='account-privacy')return;render(fragment||new URLSearchParams(location.search).get('mode')||'login');}
window.addEventListener('hashchange',navigate);
form.addEventListener('submit',async event=>{event.preventDefault();if(busy||!available||!form.reportValidity())return;if(['register','reset'].includes(mode)&&$('password').value!==$('confirm').value){feedback('The two passwords must match.',true);return;}busy=true;fields.disabled=true;feedback('Working…');try{
 const data={email:$('email').value,password:$('password').value,name:$('name').value,organisation:$('organisation').value,stakeholderType:$('stakeholder').value,consent:$('consent').checked,token};
 const result=await api(mode,data);
 if(mode==='login'){showAccount(result.user);return;}
 if(mode==='register'){render('resend');step(1);feedback('Check your inbox for the verification link. '+result.message);}
 else if(mode==='verify'||mode==='reset'){token='';render('login');feedback(result.message);}
 else feedback(result.message);
 }catch(error){feedback(error.message,true);}finally{busy=false;fields.disabled=!available;$('password').value='';$('confirm').value='';}});
$('logout').addEventListener('click',async()=>{const button=$('logout');button.disabled=true;try{await api('logout',{});render('login');feedback('You are signed out.');}catch(error){button.textContent=error.message;}finally{button.disabled=false;}});
async function start(){navigate();const requestedType=new URLSearchParams(location.search).get('type');if(types[requestedType])$('stakeholder').value=requestedType;try{const status=await api('status');available=status.available===true;$('availability').hidden=available;fields.disabled=!available;if(available&&!token){try{const result=await api('me');showAccount(result.user);}catch{ /* An unauthenticated visitor can use the account forms. */ }}}catch{$('availability').hidden=false;fields.disabled=true;}}
start();
